"""Bundled Lucide icon geometry (assets/icons/icons.json, generated by tools/gen_icons.py)."""
import json
import os

PATH = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "assets", "icons", "icons.json"))
_data = None


def get(name):
    global _data
    if _data is None:
        _data = json.load(open(PATH, encoding="utf-8"))
    if name not in _data["icons"]:
        import difflib
        from .scene import LayoutError
        near = difflib.get_close_matches(name, _data["icons"].keys(), n=4, cutoff=0.4)
        raise LayoutError("unknown icon '%s'%s. Icon names are the files in assets/icons/lucide/" % (
            name, " (did you mean %s?)" % ", ".join(near) if near else ""))
    return _data["icons"][name]


def names():
    get("calendar")
    return sorted(_data["icons"])


def svg_d(subpaths):
    out = []
    for sp in subpaths:
        for c in sp:
            out.append(c[0] + " ".join("%.3f" % v for v in c[1:]))
    return "".join(out)
